        const k2 = new Mesh(new SphereGeometry(1, 12, 8), organM); k2.scale.set(0.26, 0.2, 0.22); k2.position.set(px - 0.12, y + 0.98, pz - MPIT.d / 2 - 0.5); g.add(k2); //
