      const cupDark = new MeshStandardMaterial({ color: 0x4a2f1d, roughness: 0.9 });   // dark, so that the white garments are seen against it //
      H2.box(g, 0.14, 4.2, CL, cupDark, shelfX + 0.53, y, CZ); //
