      H2.box(g, 3.0, 0.25, 0.25, M2.cedar, cx - 0.1, y + 5.2, RZ);                          // the rail, the tunics hanging from it //
      for (const lx of [-1.4, 1.4]) H2.box(g, 0.25, 5.2, 0.25, M2.cedar, cx - 0.1 + lx, y, RZ); //
