        for (const [lx, lz] of [[-0.7, -0.42], [0.7, -0.42], [-0.7, 0.42], [0.7, 0.42]]) H2.box(g, 0.12, 1.35, 0.12, M2.cedar, tX + lx, y, tZ + lz); //
        H2.box(g, 1.0, 0.16, 0.75, linenMat, tX, y + 1.47, tZ); //
