      "  float a = body * top;", //
      "  a *= 0.75 + 0.5 * n2;", //
      "  a = clamp(a * smoothstep(0.0, 0.10, q.y), 0.0, 1.0);", //
      "  float heat = a * (1.15 - q.y * 0.75);", //
