      const n2 = flameFbm(T.vec2(q.x.mul(5.5).add(3.1), q.y.mul(3.6).sub(t.mul(2.6))).add(uSeed.mul(1.7))); //
      const sway = n1.sub(0.5).mul(0.9).mul(q.y).mul(q.y).mul(2.2); //
