        for (const [px, py] of [[276, 46], [292, 60], [268, 80], [282, 98], [252, 112], [262, 132], [228, 140], [232, 160], [198, 158]]) q.lineTo(X(px), py); //
        q.closePath(); q.fill(); q.stroke(); //
