      CN_W: [-15, -52.2], CN: [36, -48.5], NL: [65.45, -49.6], GZ_OUT: [81, -51.4], GZ_IN: [81, -57.4], GZ_C: [83.2, -61.4],   // GAZIT_PLACE_211: the hall's door, in its south wall at x 81 //
